<template><Teleport to="body"><div v-if="modelValue" class="app-dialog-backdrop" @click.self="requestClose" @keydown="keyboard"><section ref="dialog" class="app-dialog" role="dialog" aria-modal="true" :aria-labelledby="titleId" tabindex="-1"><header><h2 :id="titleId">{{ title }}</h2><button type="button" class="icon-button" aria-label="关闭弹窗" :disabled="persistent" @click="requestClose"><MobileIcon name="close" /></button></header><div class="app-dialog-body"><slot /></div><footer v-if="$slots.footer"><slot name="footer" /></footer></section></div></Teleport></template>
<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref, useId, watch } from 'vue'
import MobileIcon from './MobileIcon.vue'
import { openDialogCount } from '@/mobile/data/presentation'
const props = defineProps<{ modelValue: boolean; title: string; persistent?: boolean }>()
const emit = defineEmits<{ 'update:modelValue': [value: boolean]; close: [] }>()
const dialog = ref<HTMLElement | null>(null), titleId = useId()
let previousFocus: HTMLElement | null = null, previousOverflow = '', opened = false
function requestClose() { if (!props.persistent) { emit('update:modelValue',false); emit('close') } }
function cleanup() { if (!opened) return; opened = false; openDialogCount.value = Math.max(0,openDialogCount.value-1); if (!openDialogCount.value) document.body.style.overflow = previousOverflow; nextTick(() => { if (previousFocus?.isConnected) previousFocus.focus() }) }
watch(() => props.modelValue, async value => { if (!value) { cleanup(); return }; previousFocus = document.activeElement as HTMLElement; previousOverflow = document.body.style.overflow; opened = true; openDialogCount.value++; document.body.style.overflow = 'hidden'; await nextTick(); dialog.value?.focus() }, { immediate: true })
onBeforeUnmount(cleanup)
function keyboard(event: KeyboardEvent) { if (event.key === 'Escape') { event.preventDefault(); requestClose() }; if (event.key !== 'Tab') return; const all = Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]') || []).filter(e => e.getClientRects().length); const first = all[0], last = all[all.length-1]; if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog.value)) { event.preventDefault(); last?.focus() } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === dialog.value)) { event.preventDefault(); first?.focus() } }
</script>
<style>.app-dialog-backdrop{position:fixed;inset:0;z-index:110;display:grid;place-items:center;padding:24px;background:rgba(2,9,24,.78);backdrop-filter:blur(10px)}.app-dialog{width:min(100%,640px);max-height:calc(100dvh - 48px);overflow:auto;border:1px solid var(--m-border-strong);border-radius:24px;background:var(--m-bg-elevated);color:var(--m-text);box-shadow:0 24px 90px rgba(0,0,0,.3);outline:none}.app-dialog>header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 24px;border-bottom:1px solid var(--m-border);position:sticky;top:0;background:var(--m-bg-elevated);z-index:1}.app-dialog>header h2{font-size:20px;margin:0}.app-dialog-body{padding:24px}.app-dialog>footer{padding:16px 24px;border-top:1px solid var(--m-border);display:flex;justify-content:flex-end;gap:12px;flex-wrap:wrap}.icon-button{width:44px;height:44px;border:1px solid var(--m-border);border-radius:14px;background:var(--m-surface-2);color:var(--m-text-dim);display:inline-grid;place-items:center;cursor:pointer;flex:none}.icon-button:disabled{opacity:.45}.app-dialog .workspace-caption{margin-bottom:0}@media(max-width:480px){.app-dialog-backdrop{padding:16px}.app-dialog{max-height:calc(100dvh - 32px)}.app-dialog-body{padding:20px}}</style>
